def has_close_elements(numbers: List[float], threshold: float) -> bool:
    """
    Checks if any two numbers in the given list are closer to each other than the given threshold.

    :param numbers: List of float values
    :param threshold: The maximum absolute difference between two numbers
    :return: True if any two numbers in the list are closer to each other than the threshold, False otherwise
    """
    for i in range(len(numbers)):
        for j in range(i + 1, len(numbers)):
            if abs(numbers[i] - numbers[j]) < threshold:
                return True
    return False

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def mean_absolute_deviation(numbers: List[float]) -> float:
    mean = sum(numbers) / len(numbers)
    absolute_differences = [abs(x - mean) for x in numbers]
    return sum(absolute_differences) / len(numbers)

def max_value_on_paths(N, grid_values):
    # Initialize a 2D array to store the maximumsum of values collected on each sub-path
    dp = [[0 for _ in range(N)] for _ in range(N)]

    # Populate the first row and column with the values in grid_values
    for i in range(N):
        for j in range(N):
            if grid_values[i][j] != 0:
                dp[i][j] = grid_values[i][j]

    # Iterate over the rest of the grid, calculating the maximum sum of values for each sub-path
    for i in range(N):
        for j in range(N):
            # If the current position has a value, skip it
            if dp[i][j] != 0:
                continue

            # Calculate the maximum sum of values for the two sub-paths that end at this position
            left = 0 if j == 0 else max(dp[i][j - 1], dp[i - 1][j - 1])
            up = 0 if i == 0 else max(dp[i - 1][j], dp[i - 1][j - 1])
            dp[i][j] = max(left, up)

    # Return the maximum sum of values on the two paths
    return max(dp[N - 1][N - 1], dp[N - 1][0], dp[0][N - 1], dp[0][0])

def find_number_combinations():
    numbers = [1, 2, 3]
    combinations = []
    for i in range(len(numbers)):
        for j in range(i + 1, len(numbers)):
            for k in range(j + 1, len(numbers)):
                if numbers[i] * 2 == numbers[j] and numbers[j] * 3 == numbers[k]:
                    combinations.append((numbers[i], numbers[j], numbers[k]))
    return sorted(combinations)

def max_product(num_str, N, K):
    nums = [int(x) for x in num_str]
    if K == 0:
        return nums[0]
    if K >= N:
        return nums[-1]
    max_prod = 1
    for i in range(N - K):
        max_prod = max(max_prod, nums[i] * nums[i+1])
    for i in range(N - K):
        max_prod = max(max_prod, nums[i] * nums[i-1])
    return max_prod

